"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["80681"],{80880(e,i,t){t.r(i),t.d(i,{metadata:()=>n,default:()=>u,frontMatter:()=>p,contentTitle:()=>c,toc:()=>l,assets:()=>d});var n=JSON.parse('{"id":"nhcx/v1/api/registry/endpoints/registry-v2-participant-link-abha-policy-init","title":"Initiate ABHA policy link (v2)","description":"First half of the two-step v2 link: submits the ABHA policy link request, to be confirmed with a passcode via the validate endpoint.","source":"@site/docs/nhcx/v1/api/registry/endpoints/registry-v2-participant-link-abha-policy-init.mdx","sourceDirName":"nhcx/v1/api/registry/endpoints","slug":"/nhcx/v1/api/registry/endpoints/registry-v2-participant-link-abha-policy-init","permalink":"/docs/pr-20/docs/nhcx/v1/api/registry/endpoints/registry-v2-participant-link-abha-policy-init","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Initiate ABHA policy link (v2)","sidebar_label":"Initiate ABHA policy link (v2)","sidebar_class_name":"api-method api-method--post","description":"First half of the two-step v2 link: submits the ABHA policy link request, to be confirmed with a passcode via the validate endpoint.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-registry.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Link ABHA number to policies (V2)","permalink":"/docs/pr-20/docs/nhcx/v1/api/registry/endpoints/registry-v2-participant-link-abha-policy"},"next":{"title":"Validate ABHA policy link (v2)","permalink":"/docs/pr-20/docs/nhcx/v1/api/registry/endpoints/registry-v2-participant-link-abha-policy-validate"}}'),a=t(62540),r=t(43023),s=t(75064),o=JSON.parse('{"id":"registry_v2_participant_link_abha_policy_init","module":"Participant registry","moduleId":"registry","kind":"operation","method":"POST","path":"/v2/participant/link/abha/policy/init","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Initiate ABHA policy link (v2)","title":"Initiate ABHA policy link (v2)","description":"First half of the two-step v2 link: submits the ABHA policy link request, to be confirmed with a passcode via the validate endpoint.\\n\\n### Business purpose\\n\\nThe init variant exists so that a policy link can be confirmed out of band before it takes effect. It takes the same ParticipantLinkAbhaRequest as the direct link calls but pairs with GET /v2/participant/link/abha/policy/validate, which accepts a passcode and transactionId. This mirrors the passcode-confirmed pattern already used for participant creation (/validate) and update (/update/validate), giving payers and TPAs an approval gate on member-layer writes. The documentation describes the pairing but does not detail how the passcode is delivered for this endpoint.\\n\\n### When to use\\n\\nUse it when your NHCX instance requires the confirmed (init then validate) form of linking rather than the single-call form. It is part of member-layer setup and precedes any claim-side workflow. Call init with the full link request, keep the transaction identifier the flow returns, and then complete the link with the validate call carrying passcode and transactionId. If the confirmation is never completed, the link should not be assumed to exist; verify with /participant/get/policies.\\n\\n### Preconditions\\n\\n- A valid Bearer token from the client-credentials call (POST /get/session, form-urlencoded client_ID, client_secret, grant_type=client_credentials); tokens last 1200 seconds, so refresh before expiry.\\n- HTTP headers Accept: application/json, Content-Type: application/json and bearer_auth: Bearer (the participant service uses bearer_auth, not Authorisation).\\n- Base path for the participant service: https://apisbx.ABDM.gov.in/pmjay/sbxhcx/participanthcxservice (sandbox) or https://apisprod.NHA.gov.in/pmjay/hcx/participanthcxservice (production).\\n- This is a synchronous plain-JSON registry call: no JWE envelope, no x-hcx-* protocol headers and no correlation ID are involved.\\n- The caller must be the participant named as payerid or processingid, with a token minted from the client_ID used at participant creation.\\n- The request body is ParticipantLinkAbhaRequest: requestid (UUID), abhanumber, memberid, payerid and policies (productid, productname) are required; mobilenumber and processingid are optional.\\n\\n### Postconditions\\n\\nThe service answers synchronously with HTTP 200 and ParticipantLinkAbhaResponse (optional result and errormessage). Per the documented pattern, the link is then confirmed by GET /v2/participant/link/abha/policy/validate with the passcode and transactionId; the docs do not state that the link is visible in policy lookups before that confirmation. There is no NHCX callback. Errors return 400, 404 or 500 with the ErrorResponse envelope. For the sibling participant flows the transaction ID and passcode are valid for 24 hours; the docs do not state a separate validity for the policy link pair.\\n\\n### Common mistakes\\n\\n- Treating init as the complete link and never calling /v2/participant/link/abha/policy/validate, then reporting that get/policies returns nothing.\\n- Using a token from a client_ID other than the one used at participant creation for the payer or TPA (common mistake 10 in the NHA list); linking is refused for unauthorised parties.\\n- Mixing the case of the path: init and validate live under lower-case /v2/, while the direct V2 link uses /V2/.\\n- Swapping payerid and processingid, or omitting required fields such as requestid, memberid or the policies array.\\n\\n### Best practices\\n\\n- Persist the requestid you sent and the transaction identifier you receive together, so the validate step can be completed by a different process or after a restart.\\n- Complete the validate step promptly; the sibling participant create and update passcodes expire after 24 hours, so do not assume a longer window here.\\n- Use the same product identifiers as registered through /product/link.\\n- Confirm the outcome with /participant/get/policies before informing the provider or beneficiary.\\n- Refresh the Bearer token proactively and retry once on 401.\\n\\n### Related scenario\\n\\nAn insurer\'s policy administration team is required by its NHCX instance to confirm member links by passcode. When a new policy is issued, the system posts the ParticipantLinkAbhaRequest to /v2/participant/link/abha/policy/init and records the transaction identifier. The authorised operator receives the passcode and the system calls GET /v2/participant/link/abha/policy/validate with passcode and transactionId to complete the link. The team then checks /V2/participant/get/policies for the member\'s ABHA number and, satisfied, closes the case; the hospital will discover the policy on the beneficiary\'s next admission.\\n\\n### Specification\\n\\nChapter [Creating and updating a participant](/docs/nhcx/v1/getting-started/creating-and-updating-a-participant) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"requestid","type":"string","required":false,"description":"","encrypted":false},{"name":"abhanumber","type":"string","required":false,"description":"","encrypted":false},{"name":"mobilenumber","type":"string","required":false,"description":"","encrypted":false},{"name":"memberid","type":"string","required":false,"description":"","encrypted":false},{"name":"payerid","type":"string","required":false,"description":"","encrypted":false},{"name":"policies","type":"object[]","required":false,"description":"","encrypted":false},{"name":"policies.productid","type":"string","required":false,"description":"","encrypted":false},{"name":"policies.productname","type":"string","required":false,"description":"","encrypted":false},{"name":"processingid","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"requestid":"3c9e8d2f-5b4a-4e1c-9f7d-8a6b5c4d3e21","abhanumber":"12345678910111","mobilenumber":"9876543210","memberid":"MEM-2026-000123","payerid":"100234@sbx","policies":[{"productid":"PRD-FLOATER-01","productname":"Family Floater Gold"}],"processingid":"100235@sbx"},"responses":[{"status":"200","description":"The service answers synchronously with HTTP 200 and ParticipantLinkAbhaResponse (optional result and errormessage).","example":{"result":"success"}}],"tag":"Other operations","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/link/abha/policy/init \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"requestid\\": \\"3c9e8d2f-5b4a-4e1c-9f7d-8a6b5c4d3e21\\",\\n  \\"abhanumber\\": \\"12345678910111\\",\\n  \\"mobilenumber\\": \\"9876543210\\",\\n  \\"memberid\\": \\"MEM-2026-000123\\",\\n  \\"payerid\\": \\"100234@sbx\\",\\n  \\"policies\\": [\\n    {\\n      \\"productid\\": \\"PRD-FLOATER-01\\",\\n      \\"productname\\": \\"Family Floater Gold\\"\\n    }\\n  ],\\n  \\"processingid\\": \\"100235@sbx\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/link/abha/policy/init \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"requestid\\": \\"3c9e8d2f-5b4a-4e1c-9f7d-8a6b5c4d3e21\\",\\n  \\"abhanumber\\": \\"12345678910111\\",\\n  \\"mobilenumber\\": \\"9876543210\\",\\n  \\"memberid\\": \\"MEM-2026-000123\\",\\n  \\"payerid\\": \\"100234@sbx\\",\\n  \\"policies\\": [\\n    {\\n      \\"productid\\": \\"PRD-FLOATER-01\\",\\n      \\"productname\\": \\"Family Floater Gold\\"\\n    }\\n  ],\\n  \\"processingid\\": \\"100235@sbx\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/link/abha/policy/init\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"requestid\\": \\"3c9e8d2f-5b4a-4e1c-9f7d-8a6b5c4d3e21\\",\\n        \\"abhanumber\\": \\"12345678910111\\",\\n        \\"mobilenumber\\": \\"9876543210\\",\\n        \\"memberid\\": \\"MEM-2026-000123\\",\\n        \\"payerid\\": \\"100234@sbx\\",\\n        \\"policies\\": [\\n            {\\n                \\"productid\\": \\"PRD-FLOATER-01\\",\\n                \\"productname\\": \\"Family Floater Gold\\"\\n            }\\n        ],\\n        \\"processingid\\": \\"100235@sbx\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/link/abha/policy/init\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"requestid\\": \\"3c9e8d2f-5b4a-4e1c-9f7d-8a6b5c4d3e21\\",\\n    \\"abhanumber\\": \\"12345678910111\\",\\n    \\"mobilenumber\\": \\"9876543210\\",\\n    \\"memberid\\": \\"MEM-2026-000123\\",\\n    \\"payerid\\": \\"100234@sbx\\",\\n    \\"policies\\": [\\n      {\\n        \\"productid\\": \\"PRD-FLOATER-01\\",\\n        \\"productname\\": \\"Family Floater Gold\\"\\n      }\\n    ],\\n    \\"processingid\\": \\"100235@sbx\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let p={title:"Initiate ABHA policy link (v2)",sidebar_label:"Initiate ABHA policy link (v2)",sidebar_class_name:"api-method api-method--post",description:"First half of the two-step v2 link: submits the ABHA policy link request, to be confirmed with a passcode via the validate endpoint.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-registry.yaml",generated:!0},c,d={},l=[];function h(e){return(0,a.jsx)(s.A,{operation:o})}function u(e={}){let{wrapper:i}={...(0,r.R)(),...e.components};return i?(0,a.jsx)(i,{...e,children:(0,a.jsx)(h,{...e})}):h(e)}}}]);